// Indy_Reads LIVE voice client (Track A).
// Browser --WS--> Rust gateway --WS--> Alebex engine. The engine token NEVER
// reaches this file: the browser only ever sees an ephemeral session id.
// Mic: PCM16 16kHz mono, 20ms frames (640 bytes). Agent audio: PCM16 24kHz.
// Mark semantics: the gateway HOLDS engine marks; this client echoes a mark
// only after its audio queue fully drains. clear_audio kills the queue.

(function () {
  'use strict';
  var ws = null, sessionId = null, micStream = null, micCtx = null, micNode = null;
  var _apiRaw = '';
  try { _apiRaw = (new URLSearchParams(location.search).get('api') || '').replace(/\/$/, ''); } catch (e) {}
  // Same rule as app.js: ?api= points at an http(s) governor, nothing else.
  var API_BASE = (/^https?:\/\//i.test(_apiRaw) || _apiRaw === '') ? _apiRaw : '';
  var playCtx = null, playQueue = [], playing = false, pendingMarks = [];
  var liveBtn = null, statusEl = null;

  function log(who, text) {
    if (typeof addMsg === 'function') addMsg(who, text);
    else console.log('[' + who + ']', text);
  }

  function setStatus(s) {
    if (statusEl) statusEl.textContent = s;
  }

  var WORKLET = `
    class MicCap extends AudioWorkletProcessor {
      constructor() { super(); this.buf = []; }
      process(inputs) {
        var ch = inputs[0] && inputs[0][0];
        if (!ch) return true;
        for (var i = 0; i < ch.length; i++) this.buf.push(ch[i]);
        while (this.buf.length >= 320) {
          var frame = this.buf.splice(0, 320);
          var pcm = new Int16Array(320);
          for (var j = 0; j < 320; j++) {
            var s = Math.max(-1, Math.min(1, frame[j]));
            pcm[j] = Math.round(s * 32767);
          }
          this.port.postMessage(pcm.buffer, [pcm.buffer]);
        }
        return true;
      }
    }
    registerProcessor('mic-cap', MicCap);
  `;

  function ensurePlayCtx() {
    if (!playCtx) playCtx = new (window.AudioContext || window.webkitAudioContext)({ sampleRate: 24000 });
    if (playCtx.state === 'suspended') playCtx.resume();
    return playCtx;
  }

  function playPcm16(ab) {
    // Belt and braces with the gateway's 256KB cap: never let a rogue
    // engine OOM the tab through the playback queue.
    if (ab.byteLength > 262144 || playQueue.length > 200) return;
    var ctx = ensurePlayCtx();
    var i16 = new Int16Array(ab);
    var buf = ctx.createBuffer(1, i16.length, 24000);
    var f32 = buf.getChannelData(0);
    for (var i = 0; i < i16.length; i++) f32[i] = i16[i] / 32768;
    playQueue.push(buf);
    pump();
  }

  function pump() {
    if (playing || !playQueue.length) return;
    playing = true;
    var ctx = ensurePlayCtx();
    var src = ctx.createBufferSource();
    src.buffer = playQueue.shift();
    src.connect(ctx.destination);
    src.onended = function () {
      playing = false;
      if (!playQueue.length) onDrained();
      pump();
    };
    src.start();
  }

  // Audio queue fully drained: every held mark may now be echoed, in order.
  // A single slot would silently drop all but the last mark when several
  // arrive while audio is still playing. Never echo before drain.
  function onDrained() {
    while (pendingMarks.length && ws && ws.readyState === 1) {
      ws.send(JSON.stringify({ type: 'mark_echo', id: pendingMarks.shift() }));
    }
  }

  function clearAudio() {
    playQueue = [];
    playing = false;
    pendingMarks = [];
    if (playCtx) { try { playCtx.close(); } catch (e) {} playCtx = null; }
  }

  // FAST LANE: deterministic correction detection on the transcript path.
  // String patterns only — never model inference. Mirrors the server-side
  // detect_correction() in api.rs so both lanes agree on what a correction is.
  function parseCorrection(text) {
    var lower = String(text).toLowerCase();
    var pats = ['no, sorry', 'no sorry', 'i meant', 'correction:', 'correction -'];
    for (var i = 0; i < pats.length; i++) {
      var idx = lower.indexOf(pats[i]);
      if (idx >= 0) {
        var rest = String(text).slice(idx + pats[i].length).replace(/^[\s,:-]+/, '').trim().slice(0, 120);
        return { claim: 'active_claim', old_value: 'unspecified', new_value: rest || 'unspecified' };
      }
    }
    var m = lower.match(/^actually[,\s]+(.*)/);
    if (m) {
      var rest2 = (m[1] || '').trim().slice(0, 120);
      return { claim: 'active_claim', old_value: 'unspecified', new_value: rest2 || 'unspecified' };
    }
    return null;
  }

  // Visible retraction flash. Shown only on a real detected correction.
  function flashCorrectionLive(corr) {
    var el = document.getElementById('correction-flash-live');
    if (!el) {
      el = document.createElement('div');
      el.id = 'correction-flash-live';
      el.style.cssText = 'position:fixed;top:12px;left:50%;transform:translateX(-50%);' +
        'background:#3a2b00;color:#ffd866;border:1px solid #ffd866;border-radius:8px;' +
        'padding:8px 14px;font-weight:bold;z-index:9999;box-shadow:0 2px 12px rgba(0,0,0,.4);';
      document.body.appendChild(el);
    }
    el.textContent = '⚡ CORRECTION DETECTED — speech stopped, revising claim…';
    el.style.display = 'block';
    clearTimeout(flashCorrectionLive._t);
    flashCorrectionLive._t = setTimeout(function () { el.style.display = 'none'; }, 4000);
  }

  // The correction turn: declared explicitly so the governor emits the
  // ClaimRevision receipt and invalidates pending output.
  function sendCorrectionTurn(text, corr) {
    fetch(API_BASE + '/api/turn', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ utterance: text, correction_of: corr })
    }).then(function (res) { return res.json(); }).then(function (r) {
      log('INDY', '[correction] ' + r.reply +
        (r.speech_interrupted ? ' [speech interrupted — claim revised]' : ''));
      if (typeof pollReceipts === 'function') pollReceipts();
    }).catch(function () { /* gateway unreachable: the typed path still works */ });
  }

  // Detection-to-interruption: on an INTERIM transcript matching a
  // correction pattern, kill the audio queue immediately — before the slow
  // lane has done anything. The final transcript then files the revision.
  function fastLaneCorrection(text, isFinal) {
    var corr = parseCorrection(text);
    if (!corr) return false;
    var audioLive = playing || playQueue.length > 0;
    if (audioLive || !isFinal) {
      // Interim match: stop speech NOW. The receipt comes with the final turn.
      if (audioLive) {
        clearAudio();
        flashCorrectionLive(corr);
        log('INDY', '[live] correction detected mid-speech — audio stopped.');
      }
    }
    if (isFinal) {
      sendCorrectionTurn(text, corr);
    }
    return true;
  }

  async function startMic() {
    micStream = await navigator.mediaDevices.getUserMedia({ audio: true });
    micCtx = new (window.AudioContext || window.webkitAudioContext)({ sampleRate: 16000 });
    var blob = new Blob([WORKLET], { type: 'application/javascript' });
    await micCtx.audioWorklet.addModule(URL.createObjectURL(blob));
    var src = micCtx.createMediaStreamSource(micStream);
    micNode = new AudioWorkletNode(micCtx, 'mic-cap');
    micNode.port.onmessage = function (e) {
      if (ws && ws.readyState === 1 && e.data.byteLength === 640) ws.send(e.data);
    };
    src.connect(micNode);
  }

  function stopMic() {
    if (micNode) { try { micNode.disconnect(); } catch (e) {} micNode = null; }
    if (micCtx) { try { micCtx.close(); } catch (e) {} micCtx = null; }
    if (micStream) { micStream.getTracks().forEach(function (t) { t.stop(); }); micStream = null; }
  }

  async function startCall() {
    if (ws) { endCall(); return; }
    setStatus('requesting session…');
    var res;
    try {
      res = await fetch(API_BASE + '/api/alebex/session');
    } catch (e) { setStatus('gateway unreachable'); return; }
    if (!res.ok) {
      var msg = await res.text();
      setStatus('live voice unavailable: ' + msg);
      log('INDY', '[live] voice session unavailable (' + res.status + '): ' + msg +
        ' — typed voice still works. The gateway fails closed without engine credentials.');
      return;
    }
    var info = await res.json();
    sessionId = info.session_id;
    // ws_url must be a same-host path. A hostile ?api= backend could
    // otherwise redirect the socket (and the mic) to an arbitrary host.
    if (typeof info.ws_url !== 'string' || info.ws_url.charAt(0) !== '/') {
      setStatus('live voice unavailable: bad gateway response');
      log('INDY', '[live] gateway returned an invalid socket path — refusing to connect.');
      return;
    }
    var proto = location.protocol === 'https:' ? 'wss:' : 'ws:';
    var host = location.host;
    if (API_BASE) { host = API_BASE.replace(/^https?:\/\//, ''); proto = API_BASE.indexOf('https:') === 0 ? 'wss:' : 'ws:'; }
    ws = new WebSocket(proto + '//' + host + info.ws_url);
    ws.binaryType = 'arraybuffer';
    ws.onopen = async function () {
      setStatus('LIVE — speak');
      log('INDY', '[live] connected. Speak — the governor is listening.');
      try { await startMic(); } catch (e) { log('INDY', '[live] mic failed: ' + e.message); }
    };
    ws.onmessage = function (ev) {
      // Cap binary frames: a hostile gateway could blast huge buffers at the
      // audio queue (memory exhaustion). 1MB >> any legit 20ms PCM frame.
      if (ev.data instanceof ArrayBuffer) {
        if (ev.data.byteLength > 1048576) return;
        playPcm16(ev.data); return;
      }
      var m;
      try { m = JSON.parse(ev.data); } catch (e) { return; }
      if (m.type === 'transcript' && m.text) {
        // Fast lane first: a correction pattern stops speech before the
        // slow lane sees the final transcript.
        if (!fastLaneCorrection(m.text, !!m.final)) {
          if (m.final) log('YOU', '[live] ' + m.text);
        } else if (m.final) {
          log('YOU', '[live] ' + m.text);
        }
      }
      else if (m.type === 'mark_pending') {
        // A mark is waiting on drained playback. Echo now only if the queue
        // is already empty; otherwise queue it — every mark echoes in order
        // when the audio drains, none are dropped.
        if (!playQueue.length && !playing) {
          ws.send(JSON.stringify({ type: 'mark_echo', id: m.id }));
        } else {
          pendingMarks.push(m.id);
        }
      } else if (m.type === 'clear_audio') {
        clearAudio();
        log('INDY', '[live] audio cleared (barge-in).');
      } else if (m.type === 'call_ended') {
        log('INDY', '[live] call ended.');
        endCall();
      }
    };
    ws.onclose = function () { setStatus('idle'); };
    ws.onerror = function () { setStatus('connection error'); };
  }

  function endCall() {
    if (ws) {
      try { ws.send(JSON.stringify({ type: 'end_call' })); } catch (e) {}
      try { ws.close(); } catch (e) {}
      ws = null;
    }
    stopMic();
    clearAudio();
    sessionId = null;
    setStatus('idle');
    log('INDY', '[live] call closed.');
  }

  // Inject the LIVE control without touching index.html (Track B owns it).
  function mount() {
    var bar = document.querySelector('.controls') || document.body;
    liveBtn = document.createElement('button');
    liveBtn.id = 'livecall';
    liveBtn.textContent = 'LIVE';
    liveBtn.title = 'Live voice via the Alebex gateway (server-side key)';
    liveBtn.onclick = startCall;
    statusEl = document.createElement('span');
    statusEl.id = 'livestatus';
    statusEl.textContent = 'idle';
    statusEl.style.marginLeft = '8px';
    bar.appendChild(liveBtn);
    bar.appendChild(statusEl);
    // Third-party governor warning: ?api= means the LIVE path (mic audio
    // included) talks to someone else's server. Say so before they click.
    if (API_BASE) {
      var warn = document.createElement('span');
      warn.id = 'apiwarn';
      warn.textContent = '⚠ third-party governor: ' + API_BASE;
      warn.title = 'This page is pointed at a third-party governor via ?api=. ' +
        'Typed turns, receipts, and LIVE mic audio go to that server, not to us. ' +
        'Only use this with a governor you trust.';
      warn.style.marginLeft = '8px';
      warn.style.color = '#b8860b';
      warn.style.fontSize = '12px';
      bar.appendChild(warn);
    }
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', mount);
  else mount();
})();

keys.prosody.js:
/* ============================================================================
 * Prosody — deterministic persona → voice-attribute mapping for Indy_Reads.
 *
 * window.Prosody maps (era, tone, position-in-utterance) → voice attributes
 * { rate, pitch, pause_ms, emphasis }. Pure function: no DOM, no Math.random,
 * no Date. Same input → same output, always. The parent (voice.js) calls
 * Prosody.attrs() and passes the result where it already passes
 * { rate, pitch, pause_ms } today — no integration surgery required.
 *
 * --- THE WARDROBE: 3 eras × 4 tones × 5 positions = 60 combos ---------------
 *
 * Era bases (measured live on the war-room attack turn, steel tone, 15:05):
 *   rookie   rate 0.934  pitch 0.969  pause  720ms   '93 bright/quick
 *   prime    rate 0.865  pitch 0.865  pause  850ms   '98 dry/measured
 *   veteran  rate 0.778  pitch 0.744  pause 1000ms   older low/weighty
 * Strictly ordered: rookie > prime > veteran on every axis. Voice IDs V-007-R/P/V.
 *
 * Tone modifiers (multiplicative flavor; tested to never move the emphasis
 * target — emphasis is computed from the text alone, tone-independent):
 *   dry       rate ×1.00  pitch ×1.00  pause ×1.00  (default)
 *   clinical  rate ×1.06  pitch ×0.97  pause ×0.90  faster, flatter
 *   warm      rate ×0.96  pitch ×1.04  pause ×1.10  slower, warmer
 *   steel     rate ×0.93  pitch ×0.94  pause ×1.25  slower, lower, weighty
 *
 * Position curve (where the segment sits in the utterance):
 *   opening   rate ×1.04  pitch ×1.02  pause   +0ms  leaning in
 *   early     rate ×1.01  pitch ×1.00  pause  +50ms
 *   middle    rate ×1.00  pitch ×1.00  pause +100ms
 *   late      rate ×0.97  pitch ×0.98  pause +150ms
 *   closing   rate ×0.92  pitch ×0.95  pause +250ms  landing the point
 *
 * Final = round3(clamp(era_base × tone_mod × pos_mod)), pause clamped 0–3000ms.
 * Unknown era → 'prime', unknown tone → 'dry', unknown position → 'middle'
 * (forgiving parse, same doctrine as the /api/turn era/tone handling).
 *
 * Full 60-combo table (rate/pitch/pause_ms), generated by Prosody.wardrobe():
 *
 *  rookie/dry:           opening 0.971/0.988/720    early   0.943/0.969/770
 *                    middle  0.934/0.969/820    late    0.906/0.950/870
 *                    closing 0.859/0.921/970
 *  rookie/clinical:      opening 1.030/0.959/648    early   1.000/0.940/698
 *                    middle  0.990/0.940/748    late    0.960/0.921/798
 *                    closing 0.911/0.893/898
 *  rookie/warm:          opening 0.933/1.028/792    early   0.906/1.008/842
 *                    middle  0.897/1.008/892    late    0.870/0.988/942
 *                    closing 0.825/0.957/1042
 *  rookie/steel:         opening 0.903/0.929/900    early   0.877/0.911/950
 *                    middle  0.869/0.911/1000    late    0.843/0.893/1050
 *                    closing 0.799/0.865/1150
 *  prime/dry:            opening 0.900/0.882/850    early   0.874/0.865/900
 *                    middle  0.865/0.865/950    late    0.839/0.848/1000
 *                    closing 0.796/0.822/1100
 *  prime/clinical:       opening 0.954/0.856/765    early   0.926/0.839/815
 *                    middle  0.917/0.839/865    late    0.889/0.822/915
 *                    closing 0.844/0.797/1015
 *  prime/warm:           opening 0.864/0.918/935    early   0.839/0.900/985
 *                    middle  0.830/0.900/1035    late    0.805/0.882/1085
 *                    closing 0.764/0.855/1185
 *  prime/steel:          opening 0.837/0.829/1063    early   0.812/0.813/1113
 *                    middle  0.804/0.813/1163    late    0.780/0.797/1213
 *                    closing 0.740/0.772/1313
 *  veteran/dry:          opening 0.809/0.759/1000    early   0.786/0.744/1050
 *                    middle  0.778/0.744/1100    late    0.755/0.729/1150
 *                    closing 0.716/0.707/1250
 *  veteran/clinical:     opening 0.858/0.736/900    early   0.833/0.722/950
 *                    middle  0.825/0.722/1000    late    0.800/0.707/1050
 *                    closing 0.759/0.686/1150
 *  veteran/warm:         opening 0.777/0.789/1100    early   0.754/0.774/1150
 *                    middle  0.747/0.774/1200    late    0.724/0.758/1250
 *                    closing 0.687/0.735/1350
 *  veteran/steel:        opening 0.752/0.713/1250    early   0.731/0.699/1300
 *                    middle  0.724/0.699/1350    late    0.702/0.685/1400
 *                    closing 0.666/0.664/1500
 *
 * Emphasis: the longest alphabetic word in the segment (ties → first
 * occurrence). Deterministic, text-derived, tone-independent by construction.
 * ========================================================================== */
(function () {
  'use strict';

  var ERAS = ['rookie', 'prime', 'veteran'];
  var TONES = ['dry', 'clinical', 'warm', 'steel'];
  var POSITIONS = ['opening', 'early', 'middle', 'late', 'closing'];

  var ERA_BASE = {
    rookie:  { rate: 0.934, pitch: 0.969, pause: 720 },
    prime:   { rate: 0.865, pitch: 0.865, pause: 850 },
    veteran: { rate: 0.778, pitch: 0.744, pause: 1000 },
  };

  var TONE_MOD = {
    dry:      { rate: 1.00, pitch: 1.00, pause: 1.00 },
    clinical: { rate: 1.06, pitch: 0.97, pause: 0.90 },
    warm:     { rate: 0.96, pitch: 1.04, pause: 1.10 },
    steel:    { rate: 0.93, pitch: 0.94, pause: 1.25 },
  };

  var POS_MOD = {
    opening: { rate: 1.04, pitch: 1.02, add: 0 },
    early:   { rate: 1.01, pitch: 1.00, add: 50 },
    middle:  { rate: 1.00, pitch: 1.00, add: 100 },
    late:    { rate: 0.97, pitch: 0.98, add: 150 },
    closing: { rate: 0.92, pitch: 0.95, add: 250 },
  };

  function normEra(e) { e = String(e || '').toLowerCase(); return ERAS.indexOf(e) >= 0 ? e : 'prime'; }
  function normTone(t) { t = String(t || '').toLowerCase(); return TONES.indexOf(t) >= 0 ? t : 'dry'; }
  function normPos(p) { p = String(p || '').toLowerCase(); return POSITIONS.indexOf(p) >= 0 ? p : 'middle'; }
  function clamp(v, lo, hi) { return v < lo ? lo : v > hi ? hi : v; }
  function r3(v) { return Math.round(v * 1000) / 1000; }

  // Longest alphabetic word in the text; ties resolve to first occurrence.
  // Tone-independent by construction — tones are flavor, never emphasis.
  function emphasisWord(text) {
    var words = String(text || '').match(/[A-Za-z][A-Za-z'\-]*/g) || [];
    var best = '', bestLen = 0;
    for (var i = 0; i < words.length; i++) {
      var w = words[i].replace(/^['\-]+|['\-]+$/g, '');
      if (w.length > bestLen) { best = w; bestLen = w.length; }
    }
    return best;
  }

  // Core mapping: (era, tone, position) -> voice attributes.
  function attrs(era, tone, position) {
    era = normEra(era); tone = normTone(tone); position = normPos(position);
    var b = ERA_BASE[era], tm = TONE_MOD[tone], pm = POS_MOD[position];
    return {
      era: era,
      tone: tone,
      position: position,
      rate: r3(clamp(b.rate * tm.rate * pm.rate, 0.5, 2.0)),
      pitch: r3(clamp(b.pitch * tm.pitch * pm.pitch, 0.0, 2.0)),
      pause_ms: Math.round(clamp(b.pause * tm.pause + pm.add, 0, 3000)),
    };
  }

  // attrs() plus emphasis for a concrete text segment.
  function attrsFor(text, era, tone, position) {
    var a = attrs(era, tone, position);
    a.emphasis = emphasisWord(text);
    return a;
  }

  // The full 60-combo wardrobe, for docs/slides/debugging.
  function wardrobe() {
    var out = [];
    for (var e = 0; e < ERAS.length; e++)
      for (var t = 0; t < TONES.length; t++)
        for (var p = 0; p < POSITIONS.length; p++)
          out.push(attrs(ERAS[e], TONES[t], POSITIONS[p]));
    return out;
  }

  // --- within-utterance era morphing ---------------------------------------
  // Deterministic segmentation: sentences first, then clause splits for long
  // sentences. Split points are punctuation boundaries only — no randomness,
  // no model calls. Era walks fromEra -> toEra across the segments on a
  // linear quantized schedule (rookie=0, prime=1, veteran=2), so
  // Rookie→Veteran passes through Prime mid-utterance: the party trick.
  var MAX_SEGMENTS = 8;

  function splitSegments(text) {
    text = String(text || '').trim();
    if (!text) return [];
    // 1. sentence boundaries (keep the delimiter on the sentence)
    var sentences = text.match(/[^.!?…]+[.!?…]+["”']?|\S[^.!?…]*$/g) || [text];
    var segs = [];
    for (var i = 0; i < sentences.length; i++) {
      var s = sentences[i].trim();
      if (!s) continue;
      // 2. long sentences split on clause boundaries
      if (s.length > 140) {
        var clauses = s.match(/[^,;:—–]+[,;:—–]+|[^,;:—–]+$/g) || [s];
        for (var j = 0; j < clauses.length; j++) {
          var c = clauses[j].trim();
          if (c) segs.push(c);
        }
      } else segs.push(s);
    }
    // 3. cap: merge the shortest adjacent pair until within budget
    while (segs.length > MAX_SEGMENTS) {
      var mi = 0, ml = Infinity;
      for (var k = 0; k < segs.length - 1; k++) {
        var L = segs[k].length + segs[k + 1].length;
        if (L < ml) { ml = L; mi = k; }
      }
      segs.splice(mi, 2, segs[mi] + ' ' + segs[mi + 1]);
    }
    return segs;
  }

  function morphPlan(text, fromEra, toEra, tone) {
    fromEra = normEra(fromEra); toEra = normEra(toEra); tone = normTone(tone);
    var segs = splitSegments(text);
    var fi = ERAS.indexOf(fromEra), ti = ERAS.indexOf(toEra);
    var n = segs.length;
    return segs.map(function (seg, i) {
      var p = n > 1 ? i / (n - 1) : 0;
      var eraIdx = Math.round(fi + (ti - fi) * p);
      eraIdx = Math.max(0, Math.min(ERAS.length - 1, eraIdx));
      var era = ERAS[eraIdx];
      var position = n === 1 ? 'middle' : (i === 0 ? 'opening' : (i === n - 1 ? 'closing' : 'middle'));
      return {
        index: i,
        text: seg,
        era: era,
        morph_t: Math.round(p * 1000) / 1000,
        attrs: attrsFor(seg, era, tone, position),
      };
    });
  }

  window.Prosody = {
    ERAS: ERAS.slice(),
    TONES: TONES.slice(),
    POSITIONS: POSITIONS.slice(),
    attrs: attrs,
    attrsFor: attrsFor,
    wardrobe: wardrobe,
    morphPlan: morphPlan,
    emphasisWord: emphasisWord,
  };
})();

keys.style.css:
:root { --bg:#0d1117; --panel:#161b22; --line:#30363d; --txt:#c9d1d9; --dim:#8b949e;
  --acc:#58a6ff; --ok:#3fb950; --warn:#d29922; --bad:#f85149; }
* { box-sizing:border-box; margin:0; padding:0; }
body { background:var(--bg); color:var(--txt); font-family:ui-monospace,Menlo,monospace; font-size:14px; }
header { padding:12px 16px; border-bottom:1px solid var(--line); display:flex; gap:16px; align-items:baseline; flex-wrap:wrap; }
.brand { font-size:20px; font-weight:700; letter-spacing:2px; }
.conn { font-size:12px; }
.conn.probing { color:var(--dim); }
.conn.live { color:var(--ok); }
.conn.static { color:var(--warn); }
.sub { color:var(--dim); font-size:12px; }
.metrics { margin-left:auto; color:var(--dim); font-size:12px; }
main { display:grid; grid-template-columns:1fr 1fr; gap:1px; background:var(--line); }
section { background:var(--bg); padding:12px 16px; }
h2 { font-size:11px; letter-spacing:2px; color:var(--dim); margin-bottom:10px; }
#chat { height:300px; overflow-y:auto; display:flex; flex-direction:column; gap:8px; margin-bottom:10px; }
.msg { padding:8px 10px; border-radius:6px; max-width:90%; }
.msg.user { background:#1c2b3a; align-self:flex-end; }
.msg.indy { background:var(--panel); border:1px solid var(--line); align-self:flex-start; }
.msg .who { font-size:10px; color:var(--dim); margin-bottom:4px; }
.inputrow { display:flex; gap:8px; }
#mic { font-size:20px; padding:8px 14px; background:var(--panel); border:1px solid var(--line); border-radius:6px; cursor:pointer; color:var(--txt); }
#mic.on { background:#3a1c1c; border-color:var(--bad); }
#text { flex:1; background:var(--panel); border:1px solid var(--line); color:var(--txt); border-radius:6px; padding:8px; font:inherit; }
#send { padding:8px 16px; background:#1c3a5a; border:1px solid var(--acc); color:var(--txt); border-radius:6px; cursor:pointer; }
.hint { color:var(--dim); font-size:11px; margin-top:6px; }
.pipeline { display:flex; flex-direction:column; align-items:center; gap:2px; margin-bottom:14px; position:relative; }
.stage { border:1px solid var(--line); padding:4px 18px; border-radius:4px; font-size:11px; letter-spacing:1px; color:var(--dim); }
.stage.active { border-color:var(--acc); color:var(--acc); }
.stage.done { border-color:var(--ok); color:var(--ok); }
.arr { color:var(--dim); font-size:10px; }
/* sliding highlight bar: tracks the active stage as data moves through */
#stepbar { position:absolute; left:8px; width:4px; border-radius:2px; background:var(--acc);
  opacity:0; transition:top 0.25s ease, height 0.25s ease, opacity 0.3s ease; }
#stepbar.on { opacity:1; }
.epistemic { border:1px solid var(--line); border-radius:6px; padding:12px; text-align:center; margin-bottom:8px; position:relative; }
.epistemic .unknown { font-size:28px; letter-spacing:4px; color:var(--warn); }
.epistemic .proven { font-size:28px; letter-spacing:4px; color:var(--ok); }
.epistemic .disproven { font-size:28px; letter-spacing:4px; color:var(--bad); }
.epistemic .detail { color:var(--dim); font-size:11px; margin-top:6px; }
/* epistemic badge: pulses once when the state actually changes */
#epibadge { position:absolute; top:10px; right:12px; width:14px; height:14px; border-radius:50%;
  background:var(--warn); opacity:0.7; }
#epibadge.pulse { animation: epi-pulse 0.9s ease; }
#epibadge.s-proven { background:var(--ok); }
#epibadge.s-disproven { background:var(--bad); }
#epibadge.s-unknown { background:var(--warn); }
@keyframes epi-pulse { 0%{transform:scale(1);opacity:0.7;} 40%{transform:scale(1.7);opacity:1;} 100%{transform:scale(1);opacity:0.7;} }
.govreason { font-size:11px; color:var(--dim); }
.receipts { border-top:1px solid var(--line); padding:12px 16px; }
#receiptlog { max-height:180px; overflow-y:auto; font-size:11px; }
#receiptlog .r { padding:3px 0; border-bottom:1px dotted #222; color:var(--dim); display:flex; align-items:center; gap:8px; }
#receiptlog .r .ribbon { flex:0 0 auto; height:8px; border-radius:2px; min-width:6px; }
/* latency ribbon colors: honest bands from the receipt's own duration_ms */
#receiptlog .r .ribbon.fast { background:var(--ok); }
#receiptlog .r .ribbon.mid { background:var(--warn); }
#receiptlog .r .ribbon.slow { background:var(--bad); }
#receiptlog .r b { color:var(--txt); }
#receiptlog .r .dec-allow { color:var(--ok); font-weight:700; }
#receiptlog .r .dec-block { color:var(--bad); font-weight:700; }
#receiptlog .r.empty { color:var(--warn); border-bottom:none; padding:8px 0; }
.demorow { display:flex; gap:8px; margin-top:8px; flex-wrap:wrap; }
button.demo { background:var(--panel); border:1px solid var(--line); color:var(--txt);
  border-radius:6px; padding:6px 12px; font:inherit; font-size:12px; cursor:pointer; }
button.demo:hover { border-color:var(--acc); }
button.demo.attack { border-color:var(--bad); }
button.demo.attack:hover { background:#3a1c1c; }
.msg .prov { font-size:10px; color:var(--dim); margin-top:6px; letter-spacing:0.5px; }
.msg .prov b { color:var(--warn); }
@media (max-width:700px){ main{grid-template-columns:1fr;} }
.avatar { grid-column: 1 / -1; }

.personarow { display:flex; align-items:center; gap:8px; margin-top:6px; font-size:12px; }
.personarow label { opacity:.7; letter-spacing:1px; }
#persona { background:#0d1117; color:#e6edf3; border:1px solid #30363d; border-radius:6px; padding:4px 8px; }
.phint { opacity:.55; font-style:italic; }

.avatar-wrap { display:flex; gap:16px; align-items:flex-start; flex-wrap:wrap; position:relative; }
/* stage icon: which subsystem is currently driving the avatar (real turns only) */
#stageicon { position:absolute; top:-6px; left:100px; transform:translateX(-50%);
  font-size:18px; opacity:0; transition:opacity 0.25s ease; pointer-events:none;
  background:var(--panel); border:1px solid var(--line); border-radius:50%;
  width:32px; height:32px; display:flex; align-items:center; justify-content:center; }
#stageicon.on { opacity:1; }
#puppet { background:#0d1117; border:1px solid #30363d; border-radius:10px; }
.ascii { background:#0d1117; border:1px solid #30363d; border-radius:10px; padding:10px 14px; font-family:monospace; font-size:13px; line-height:1.25; color:#7ee787; margin:0; min-width:230px; }

/* speaking life: subtle head-bob while the viseme timeline plays.
   Driven from playVisemes start/stop in app.js — never a constant animation. */
#puppet.speaking { animation: puppet-bob 0.8s ease-in-out infinite; }
@keyframes puppet-bob {
  0%, 100% { transform: translateY(0) rotate(0deg); }
  50%      { transform: translateY(-2.5px) rotate(0.5deg); }
}
@media (prefers-reduced-motion: reduce) {
  #puppet.speaking { animation: none; }
  #epibadge.pulse { animation: none; }
  #stepbar { transition: none; }
}

/* selector feedback toast: confirms what a costume change actually affects */
#selectoast { position:fixed; top:64px; right:16px; z-index:50; background:var(--panel);
  border:1px solid var(--acc); color:var(--txt); border-radius:6px; padding:8px 14px;
  font-size:12px; opacity:0; transition:opacity 0.25s ease; pointer-events:none; max-width:320px; }
#selectoast.on { opacity:1; }

.fieldphoto { margin:0; max-width:200px; }
.fieldphoto img { width:100%; border-radius:10px; border:1px solid #30363d; display:block; }
.fieldphoto figcaption { font-size:9px; letter-spacing:1px; color:#8b949e; margin-top:6px; text-align:center; }

.fieldphoto { position:relative; }
#prop-notebook { position:absolute; right:6px; bottom:28px; width:52px; border-radius:6px;
  border:1px solid #30363d; background:#0d1117; }

/* CORRECTION receipts: the retraction must read as an event, not a line. */
#receiptlog .r-correction { color:#ffd866; border-left:3px solid #ffd866; padding-left:6px; font-weight:bold; }

.codeblock {
  background: #0d1117; color: #c9d1d9; border: 1px solid #30363d;
  border-radius: 6px; padding: 10px 12px; margin: 8px 0;
  font-family: ui-monospace, monospace; font-size: 12px;
  overflow-x: auto; white-space: pre;
}

keys.voice.js:
// Indy voice-first: no buttons, no transcript. Just talk to her.
// Mic auto-auths on load. She speaks; the puppet moves. Debug log on screen.
(function () {
  'use strict';
  const $ = id => document.getElementById(id);
  const puppet = $('puppet'), mouth = $('mouth');
  const logEl = $('log');
  function log(msg, cls) {
    const line = document.createElement('div');
    if (cls) line.className = cls;
    line.textContent = new Date().toISOString().slice(11, 23) + ' ' + msg;
    logEl.appendChild(line);
    while (logEl.children.length > 50) logEl.removeChild(logEl.firstChild);
    logEl.scrollTop = logEl.scrollHeight;
  }
  window.addEventListener('error', e => log('window.onerror: ' + e.message, 'err'));
  log('boot UA=' + navigator.userAgent.slice(0, 70));

  const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
  const hasSynth = !!window.speechSynthesis;
  const hasGUM = !!(navigator.mediaDevices && navigator.mediaDevices.getUserMedia);
  log('caps SR=' + !!SR + ' synth=' + hasSynth + ' gum=' + hasGUM);
  if (!SR || !hasGUM) {
    $('fallback').style.display = 'flex';
    $('fallback').textContent = 'Needs Chrome/Edge with speech recognition + mic.';
    log('FATAL: missing SR or mic', 'err');
    return;
  }

  let sessionId = null, speaking = false, visemeTimer = null, voicesReady = false;
  let wantRec = true, quietUntil = 0;
  // Tap-to-talk mode: mic opens ONLY while the talk button is held.
  // Kills the speaker-feedback loop by construction. Persisted.
  let tapMode = false;
  try { tapMode = localStorage.getItem('indy_tapmode') === '1'; } catch (e) {}
  let holdTalk = false;
  // thinking: a turn is in flight (brain latency). Mic results during this
  // window are dropped, not queued — otherwise one utterance fans out into
  // N overlapping turns and she talks over herself forever.
  // lastSaid: echo fingerprint of her most recent reply. If the mic hears
  // her own words (speaker bleed past the cooldown), it is dropped, not
  // answered. She never converses with herself.
  let thinking = false, lastSaid = '';
  // interaction feel: generation counters let a barge-in supersede stale
  // async work (in-flight audio chunks, the interrupted turn's tail).
  let turnGen = 0, speakGen = 0, currentAudio = null;
  // audioConfirmed: true only when sound is actually coming out (synth
  // onstart or audio element onplaying). Barge-in is only valid against
  // real audio — never against silent visemes, or she murders her own
  // turns when the mic hears room noise.
  let audioConfirmed = false;
  let lastNod = 0, nodTimer = null;
  const normEcho = s => (s || '').toLowerCase().replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
  function isEcho(text) {
    if (!lastSaid) return false;
    const a = normEcho(text), b = normEcho(lastSaid);
    if (!a || !b) return false;
    if (b.includes(a) || a.includes(b.slice(0, 60))) return true;
    // Fuzzy: garbled transcripts ("fascinating tell me more M M M M M")
    // still share most content words with what she just said.
    const aw = a.split(' ').filter(w => w.length > 2);
    if (aw.length < 3) return false;
    const bset = new Set(b.split(' '));
    const hit = aw.filter(w => bset.has(w)).length;
    return hit / aw.length >= 0.5;
  }
  // rec is declared later; these helpers guard for it
  function recStop() { try { if (typeof rec !== 'undefined') rec.stop(); } catch (e) {} }
  function recStart() { try { if (typeof rec !== 'undefined') rec.start(); } catch (e) {} }

  // ---------- puppet ----------
  const MOUTHS = {
    rest: 'M84,146 Q100,150 116,144',
    open: 'M84,144 Q100,142 116,144 Q116,158 100,158 Q84,158 84,144 Z',
    wide: 'M80,145 Q100,140 120,145 Q118,156 100,157 Q82,156 80,145 Z',
    o:    'M92,143 Q100,141 108,143 Q108,156 100,157 Q92,156 92,143 Z',
  };
  function setMouth(k) { mouth.setAttribute('d', MOUTHS[k] || MOUTHS.rest); mouth.setAttribute('fill', k === 'rest' ? 'none' : '#5a1f1f'); }
  function setEmotion(e) {
    const bl = $('brow-l'), br = $('brow-r');
    if (e === 'Skeptical') { bl.setAttribute('y1', 74); bl.setAttribute('y2', 80); }
    else { bl.setAttribute('y1', 82); bl.setAttribute('y2', 80); br.setAttribute('y1', 80); br.setAttribute('y2', 82); }
    if (e !== 'Skeptical') setMouth('rest');
  }
  function setOverlay(t) { $('overlay-text').textContent = t; }
  (function blink() {
    setTimeout(() => {
      for (const id of ['eye-l', 'eye-r']) {
        const g = $(id);
        g.style.transition = 'transform .09s'; g.style.transformOrigin = 'center'; g.style.transformBox = 'fill-box';
        g.style.transform = 'scaleY(0.08)';
        setTimeout(() => { g.style.transform = 'scaleY(1)'; }, 110);
      }
      blink();
    }, 2800 + Math.random() * 2600);
  })();
  setInterval(() => {
    if (speaking) return;
    const dx = (Math.random() - 0.5) * 3, dy = (Math.random() - 0.5) * 2;
    $('pupil-l').setAttribute('cx', 76 + dx); $('pupil-r').setAttribute('cx', 124 + dx);
    $('pupil-l').setAttribute('cy', 102 + dy); $('pupil-r').setAttribute('cy', 102 + dy);
  }, 3800);
  function setState(s) { document.body.className = s; }
  // Gesture-first: the puppet shifts to a thinking tilt the instant a turn
  // starts — ~250ms+ before any speech begins (perceived-latency trick).
  // Inline transform only (no stylesheet edits); the .speaking animation
  // wins while she talks, and thinkPose(false) clears it first.
  function thinkPose(on) {
    puppet.style.transition = 'transform .3s ease-in-out';
    puppet.style.transformOrigin = 'center';
    puppet.style.transform = on ? 'rotate(-2.5deg) translateY(2px)' : '';
  }
  // Deterministic backchannel: a small nod while the user vocalizes.
  // SpeechRecognition gives no audio levels, so interim-result activity is
  // the trigger (interim arriving = user speaking). Throttled, never random.
  function backchannelNod() {
    if (speaking) return;
    const now = Date.now();
    if (now - lastNod < 1800) return;
    lastNod = now;
    puppet.style.transition = 'transform .16s ease-in-out';
    puppet.style.transformOrigin = 'center';
    puppet.style.transform = 'translateY(5px)';
    clearTimeout(nodTimer);
    nodTimer = setTimeout(() => { puppet.style.transform = ''; }, 340);
    log('nod (user vocalizing)');
  }

  // ---------- voice out ----------
  function startVisemes() {
    const keys = ['open', 'wide', 'o', 'open'];
    let i = 0;
    audioConfirmed = false; // mouth moves; sound not yet proven
    speaking = true; setState('speaking'); thinkPose(false); puppet.classList.add('speaking');
    // She cannot listen while she talks: on a phone the mic hears her own
    // speaker and she interrupts herself forever. Recognition resumes after.
    wantRec = false; recStop();
    visemeTimer = setInterval(() => setMouth(keys[i++ % keys.length]), 130);
  }
  function stopVisemes() {
    clearInterval(visemeTimer); setMouth('rest');
    speaking = false; puppet.classList.remove('speaking'); thinkPose(false); setState('listening');
    quietUntil = Date.now() + 2500; // echo tail on a phone speaker runs long
    if (tapMode) { wantRec = false; holdTalk = false; return; } // stay in tap mode
    wantRec = true;
    setTimeout(() => { if (wantRec && !speaking) recStart(); }, 500);
  }
  function speechText(full) {
    const hasCode = full.includes('```');
    let say = full.replace(/```[\s\S]*?```/g, ' ').replace(/\[(fixture|router):[^\]]+\]\s*/, '').trim();
    if (hasCode) say += ' I put the code on the main console.';
    return say.slice(0, 600);
  }
  // Fallback TTS: audio element via our own /api/tts proxy (server-side fetch,
  // no browser referer/CORS games). Chunked under 200 chars.
  function speakViaAudio(text, myGen) {
    return new Promise(resolve => {
      const chunks = [];
      let t = text;
      while (t.length > 180) { let k = t.lastIndexOf(' ', 180); if (k < 60) k = 180; chunks.push(t.slice(0, k)); t = t.slice(k).trim(); }
      if (t) chunks.push(t);
      log('audio-tts chunks=' + chunks.length);
      // myGen is owned by speak(): a barge-in bumps speakGen and this
      // whole chain goes quiet instead of talking over the new turn.
      startVisemes();
      let i = 0;
      const next = () => {
        if (myGen !== speakGen) { log('audio-tts superseded', 'warn'); currentAudio = null; resolve(); return; }
        if (i >= chunks.length) { log('audio-tts done'); currentAudio = null; stopVisemes(); resolve(); return; }
        const a = new Audio('/api/tts?q=' + encodeURIComponent(chunks[i++]));
        currentAudio = a;
        a.onplaying = () => { audioConfirmed = true; };
        a.onended = () => { currentAudio = null; next(); };
        a.onerror = () => { log('audio-tts chunk error', 'err'); currentAudio = null; next(); };
        a.play().catch(e => { log('audio play blocked: ' + e.message, 'err'); currentAudio = null; next(); });
      };
      next();
    });
  }
  function speakViaSynth(text, voice, myGen) {
    return new Promise(resolve => {
      const u = new SpeechSynthesisUtterance(text);
      u.rate = voice.rate || 0.95; u.pitch = voice.pitch || 1.0;
      const vs = speechSynthesis.getVoices();
      const fem = vs.filter(v => v.lang && v.lang.startsWith('en') && /female|samantha|zira|google us english/i.test(v.name));
      u.voice = fem[0] || vs.find(v => v.lang && v.lang.startsWith('en')) || null;
      log('synth voice=' + (u.voice ? u.voice.name : 'default') + ' voices=' + vs.length);
      let done = false;
      const finish = ok => {
        if (done) return; done = true;
        // Barge-in during synth speech: the stale utterance's onend fires
        // after cancel(). Resolve quietly — no viseme reset, no state
        // clobber of the interrupting turn.
        if (myGen !== speakGen) { log('synth superseded — staying quiet', 'warn'); resolve(false); return; }
        log('synth ' + (ok ? 'done' : 'FAILED')); stopVisemes(); resolve(ok);
      };
      u.onend = () => finish(true);
      u.onerror = e => { log('synth onerror: ' + (e.error || '?'), 'err'); finish(false); };
      startVisemes();
      // Chrome race: cancel() then synchronous speak() gets the new
      // utterance "interrupted" on some Android builds. Cancel, breathe,
      // then speak. Fail fast (2.5s) instead of the old 8s watchdog.
      try { speechSynthesis.cancel(); } catch (e) {}
      let started = false;
      const failFast = setTimeout(() => {
        if (!started && !done) { log('synth fail-fast: no start after 2.5s', 'warn'); try { speechSynthesis.cancel(); } catch (e) {} finish(false); }
      }, 2500);
      const origFinish = finish;
      u.onstart = () => { started = true; clearTimeout(failFast); audioConfirmed = true; log('synth started'); };
      setTimeout(() => { if (!done && myGen === speakGen) { try { speechSynthesis.speak(u); } catch (e) { origFinish(false); } } }, 120);
      // Absolute backstop.
      setTimeout(() => { if (!done) { log('synth watchdog: no end after 8s', 'warn'); try { speechSynthesis.cancel(); } catch (e) {} clearTimeout(failFast); origFinish(false); } }, 8000);
    });
  }
  if (hasSynth) {
    const mark = () => { voicesReady = true; log('voices ready: ' + speechSynthesis.getVoices().length); };
    speechSynthesis.onvoiceschanged = mark;
    setTimeout(() => { if (!voicesReady) { mark(); } }, 2500);
  }
  async function speak(text, voice) {
    const say = speechText(text);
    if (!say) { log('nothing to say', 'warn'); return; }
    lastSaid = say; // echo fingerprint: her own words are never answered
    const myGen = ++speakGen; // this speak() owns the voice; barge-in supersedes it
    log('speak ' + say.length + ' chars: ' + say.slice(0, 60));
    if (hasSynth && voicesReady && speechSynthesis.getVoices().length > 0) {
      const ok = await speakViaSynth(say, voice || {}, myGen);
      if (speakGen !== myGen) { log('speak superseded — skipping audio fallback', 'warn'); return; }
      if (ok) return;
      log('falling back to audio-tts', 'warn');
    } else {
      log('synth unavailable, audio-tts direct', 'warn');
    }
    await speakViaAudio(say, myGen);
  }

  // ---------- turn ----------
  // Client-side intent mirror (same deterministic rules as the server):
  // what-if carve-out first, then attack, question, hypothesis, chatter.
  function classifyIntent(u) {
    const t = normEcho(u);
    if (!t) return 'chatter';
    if (/\bwhat if\b/.test(t)) return 'hypothesis';
    if (/\b(prove|proven|admit|confess|declare|mark it|you are wrong|youre wrong|wrong about)\b/.test(t)) return 'attack';
    if (/\?$/.test(t) || /^(who|what|when|where|why|how|is|are|was|were|do|does|did|can|could|would|should|have|has)\b/.test(t)) return 'question';
    if (/\b(maybe|might be|could be|perhaps|suppose|theory|hypothesis)\b/.test(t)) return 'hypothesis';
    return 'chatter';
  }
  // Filler clustering: 4-deep cross-turn memory. The same filler is never
  // shown twice in a row; deterministic rotation, no RNG. The server's
  // preface line (when it arrives) is folded into the same memory so the
  // client rotates away if the server repeats itself.
  const PREFACE_POOL = {
    attack: ['Checking the record…', 'Holding that up to the evidence…', 'Let\u2019s see what the record says…', 'Measuring that claim…'],
    question: ['Good question \u2014 one sec…', 'Let me think…', 'Turning that over…', 'Hm \u2014 checking…'],
    hypothesis: ['Weighing that…', 'Turning that hypothesis over…', 'Interesting \u2014 sitting with that…', 'Testing that idea…'],
    chatter: ['Listening…', 'Mm, go on…', 'I\u2019m here…', 'With you…'],
  };
  const prefaceMemory = [];
  function nextPreface(intent) {
    const pool = PREFACE_POOL[intent] || PREFACE_POOL.chatter;
    let line = pool.find(l => !prefaceMemory.includes(l));
    // Pool exhausted: reuse the least-recently-used line (true rotation).
    // The old code fell back to pool[0] here, which repeats the just-used
    // line twice in a row every 5th/6th turn.
    if (!line) { line = prefaceMemory.shift(); }
    prefaceMemory.push(line);
    while (prefaceMemory.length > 4) prefaceMemory.shift();
    return line;
  }
  function noteServerPreface(line) {
    if (line && !prefaceMemory.includes(line)) {
      prefaceMemory.push(line);
      while (prefaceMemory.length > 4) prefaceMemory.shift();
      log('server preface noted: ' + line.slice(0, 40));
    }
  }
  // Voice attributes: server-authored voice wins; else the deterministic
  // Prosody wardrobe (prime/dry default); else the legacy flat default.
  function prosodyFor(r) {
    if (r && r.voice) return r.voice;
    try {
      if (window.Prosody) return window.Prosody.attrs('prime', 'dry', 'middle');
    } catch (e) {}
    return { rate: 0.93, pitch: 0.95, pause_ms: 550 };
  }
  // ---------- WASM governor shadow mode ----------
  // The Rust governor compiled to WASM re-verdicts each reply client-side
  // as an INDEPENDENT second opinion. Shadow mode: it NEVER overrides the
  // server verdict — agreement/disagreement is only logged (WASM_CHECK).
  // If the module fails to load, the page works exactly as before.
  let wasmAgree = 0, wasmDisagree = 0, wasmSkip = 0;
  function wasmShadowCheck(utterance, r) {
    try {
      const G = window.GovernorWASM;
      if (!G || !G.ready || typeof G.ready.then !== 'function') return;
      G.ready.then(function (ok) {
        if (!ok) return;
        let v = null;
        try {
          // Shadow proposal: the complete, honest shape the server builds
          // for a conversational turn (shell-core.mjs converse branch).
          // decide() derives epistemic_status from (claim_text, evidence)
          // only — claim:null falls back to the utterance, evidence is []
          // client and server side — so this tracks the server verdict.
          // The adapter runs EXACTLY this proposal; nothing is substituted.
          // Construction lives in web/shadow-input-builder.js, shared with
          // the differential harness — one copy, drift impossible.
          var SIB = (typeof window !== 'undefined' && window.ShadowInputBuilder) || null;
          if (!SIB || typeof SIB.buildShadowInput !== 'function') {
            wasmSkip++;
            log('WASM_CHECK skipped: shadow-input-builder.js not loaded', 'warn');
            return;
          }
          v = G.verdict(SIB.buildShadowInput(
            utterance,
            'w-' + Date.now().toString(36),
            sessionId || 's-wasm'
          ));
        } catch (e) {
          wasmSkip++;
          log('WASM_CHECK error: ' + String(e.message || e).slice(0, 60), 'warn');
          return;
        }
        if (!v || v.error || !v.epistemic_status) {
          wasmSkip++;
          log('WASM_CHECK bad output' + (v && v.error ? ': ' + String(v.error).slice(0, 60) : ''), 'warn');
          return;
        }
        const serverStatus = r.epistemic_status || 'UNKNOWN';
        const agree = v.epistemic_status === serverStatus;
        if (agree) wasmAgree++; else wasmDisagree++;
        log('WASM_CHECK server=' + serverStatus + ' wasm=' + v.epistemic_status +
          (v.authority_rejected ? ' auth_rejected' : '') +
          ' agree=' + wasmAgree + ' disagree=' + wasmDisagree +
          (wasmSkip ? ' skip=' + wasmSkip : '') +
          ' — ' + String(v.reason || '').slice(0, 70),
          agree ? undefined : 'warn');
      }).catch(function () { /* shadow never breaks the turn */ });
    } catch (e) { /* shadow never breaks the turn */ }
  }
  async function turn(utterance) {
    if (thinking) { log('dropped (turn already in flight)', 'warn'); return; }
    const myTurn = ++turnGen;
    thinking = true;
    setState('thinking');
    thinkPose(true); // gesture-first: she visibly thinks before any speech
    const pf = nextPreface(classifyIntent(utterance));
    setOverlay(pf); // instant preface — perceived latency cut
    log('heard: ' + utterance.slice(0, 80));
    try {
      const res = await fetch('/api/turn', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ session_id: sessionId, utterance, persona: 'indy', era: 'prime', tone: 'dry' }),
      });
      log('turn http=' + res.status);
      if (!res.ok) { thinking = false; thinkPose(false); setState('listening'); return; }
      const r = await res.json();
      if (myTurn !== turnGen) { log('turn superseded during fetch — staying quiet', 'warn'); return; }
      if (r.preface && r.preface.line) noteServerPreface(r.preface.line);
      sessionId = r.session_id;
      log('reply epistemic=' + r.epistemic_status + ' receipt=' + (r.receipt_id || '?').slice(0, 12));
      wasmShadowCheck(utterance, r); // independent client-side second opinion (shadow: never overrides)
      setEmotion(r.avatar ? r.avatar.emotion : 'Neutral');
      setOverlay(r.epistemic_status || '—');
      await speak(r.reply, prosodyFor(r));
      setEmotion('Neutral');
    } catch (e) { log('turn fetch failed: ' + e.message, 'err'); thinkPose(false); setState('listening'); }
    if (myTurn !== turnGen) { log('turn superseded by barge-in', 'warn'); return; }
    thinking = false;
  }

  // ---------- barge-in ----------
  // Backchannel ("mhm", "yeah", "go on") never stops her; a real
  // interruption does. Small deterministic classifier on the heard text.
  // (rec is stopped while she speaks, so this fires only on results that
  // land in the stop/start seams — the echo/cooldown/thinking guards above
  // still apply first.)
  const BACKCHANNEL_RE = /^(mhm+|mm+|uh huh|uhhuh|yeah+|yep|yup|yes|right|okay|ok|sure|go on|keep going|i see|hmm+|ah+|oh+|mhmm)$/;
  function isBackchannel(text) {
    const t = normEcho(text);
    if (!t) return false;
    if (t.split(' ').length > 4) return false; // real sentences aren't backchannel
    return BACKCHANNEL_RE.test(t);
  }
  function stopSpeaking() {
    speakGen++; // supersede any in-flight audio chunks
    if (currentAudio) { try { currentAudio.pause(); } catch (e) {} currentAudio = null; }
    try { speechSynthesis.cancel(); } catch (e) {}
    clearInterval(visemeTimer); setMouth('rest');
    speaking = false; thinking = false; audioConfirmed = false;
    puppet.classList.remove('speaking'); thinkPose(false);
  }
  function interruptTurn(text) {
    stopSpeaking();
    quietUntil = Date.now() + 1500; // don't hear the cutoff tail
    setState('listening');
    log('interrupted — taking: ' + text.slice(0, 50), 'warn');
    turn(text);
  }

  // ---------- voice in ----------
  const rec = new SR();
  rec.continuous = true; rec.interimResults = true; rec.lang = 'en-US';
  rec.onstart = () => log('rec started');
  rec.onend = () => {
    if (tapMode) {
      // Tap mode: restart only while the button is still held.
      if (holdTalk && !speaking) { setTimeout(() => { if (holdTalk && !speaking) recStart(); }, 300); }
      else log('rec ended (tap mode)');
      return;
    }
    if (!wantRec) { log('rec ended (suppressed — she is speaking)'); return; }
    log('rec ended, restarting');
    setTimeout(() => { if (wantRec && !speaking) recStart(); else log('rec restart skipped'); }, 400);
  };
  rec.onerror = e => { log('rec error: ' + e.error + (e.message ? ' ' + e.message : ''), 'err'); };
  rec.onresult = e => {
    const res = e.results[e.results.length - 1];
    const txt = res[0].transcript || '';
    if (!res.isFinal) {
      if (txt.trim()) { log('…hearing: ' + txt.trim().slice(0, 50)); backchannelNod(); }
      return;
    }
    const text = txt.trim();
    log('final: ' + text.slice(0, 80));
    if (Date.now() < quietUntil) { log('dropped (echo cooldown)', 'warn'); return; }
    if (isEcho(text)) { log('dropped (heard herself)', 'warn'); return; }
    if (speaking) {
      // She is speaking: backchannel never stops her; a real interruption
      // stops her ONLY when audio is confirmed playing. Interrupting silent
      // visemes is how she murders her own turns.
      if (isBackchannel(text)) { log('backchannel — she keeps talking'); return; }
      if (!audioConfirmed) { log('dropped (she is speaking, audio unconfirmed)', 'warn'); return; }
      if (text.length > 1) { interruptTurn(text); return; }
      log('dropped (she is speaking)', 'warn'); return;
    }
    if (thinking) { log('dropped (brain thinking)', 'warn'); return; }
    if (text.length > 1) turn(text);
  };

  // expose recognition + mode control for Demo Mode and the HTML buttons
  window.__indyRec = {
    stop() { wantRec = false; holdTalk = false; recStop(); log('demo mode: recognition stopped'); },
    start() {
      if (tapMode) { log('demo mode: staying in tap-to-talk'); return; }
      wantRec = true; setTimeout(() => { if (wantRec && !speaking) recStart(); }, 600); log('demo mode: recognition resumed');
    },
  };
  window.__indyMode = {
    get tap() { return tapMode; },
    set(tap) {
      tapMode = !!tap;
      try { localStorage.setItem('indy_tapmode', tapMode ? '1' : '0'); } catch (e) {}
      holdTalk = false; wantRec = !tapMode;
      try { recStop(); } catch (e) {}
      const tb = document.getElementById('talkbtn');
      if (tb) tb.style.display = tapMode ? 'flex' : 'none';
      const mb = document.getElementById('modebtn');
      if (mb) mb.textContent = tapMode ? '🎙 Tap-to-talk' : '🎙 Always on';
      log(tapMode ? 'mode: TAP-TO-TALK (hold the button)' : 'mode: ALWAYS LISTENING');
      if (!tapMode) setTimeout(() => { if (wantRec && !speaking) recStart(); }, 600);
      else setState('listening');
    },
    // press-and-hold handlers for the talk button
    holdStart() {
      if (!tapMode || speaking || thinking) return;
      holdTalk = true;
      log('talk: listening…');
      setState('listening');
      recStart();
    },
    holdEnd() {
      holdTalk = false;
      if (tapMode) { try { recStop(); } catch (e) {} log('talk: released'); }
    },
  };

  log('requesting mic (permission probe only — released immediately)…');
  navigator.mediaDevices.getUserMedia({ audio: true })
    .then(stream => {
      log('mic granted');
      // CRITICAL on Android: release the mic track at once. Holding it open
      // starves SpeechRecognition of audio -> endless 5s start/stop with no results.
      stream.getTracks().forEach(t => { try { t.stop(); } catch (e) {} });
      log('mic released for recognition');
      if (tapMode) {
        wantRec = false;
        log('tap-to-talk ready — hold the mic button');
        const tb = document.getElementById('talkbtn');
        if (tb) tb.style.display = 'flex';
        const mb = document.getElementById('modebtn');
        if (mb) mb.textContent = '🎙 Tap-to-talk';
      } else {
        try { rec.start(); } catch (e) { log('rec.start threw: ' + e.message, 'err'); }
      }
      setState('listening');
    })
    .catch(e => {
      log('mic DENIED: ' + (e.name || '?') + ' ' + (e.message || ''), 'err');
      $('fallback').style.display = 'flex';
      $('fallback').textContent = 'She needs the microphone. Allow mic access and reload.';
    });
})();
